'use client';

import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { icons } from '../utils/icons';
import { formatCurrency, formatNumber, formatDateShort } from '../utils/formatters';

export default function DashboardView({ onOpenNewSale, onOpenInvoiceView }) {
  const { metrics, hideAmounts, sales, setActiveTab } = useApp();
  const [chartMode, setChartMode] = useState('sales'); // 'sales' | 'profit'
  const [timeframe, setTimeframe] = useState('week'); // 'week' | 'month' | 'year'
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);

  // Filter sales for selected date
  const filteredSales = sales.filter(s => s.date.startsWith(selectedDate));

  // Step date forward/backward
  const stepDate = (days) => {
    const d = new Date(selectedDate);
    d.setDate(d.getDate() + days);
    setSelectedDate(d.toISOString().split('T')[0]);
  };

  // Mock weekly data for interactive chart
  const weekData = [
    { day: 'Wed', date: '14 Oct', sales: 48000, profit: 9200 },
    { day: 'Thu', date: '15 Oct', sales: 72000, profit: 14500 },
    { day: 'Fri', date: '16 Oct', sales: 125000, profit: 24000 },
    { day: 'Sat', date: '17 Oct', sales: 94000, profit: 18200 },
    { day: 'Sun', date: '18 Oct', sales: 32000, profit: 6400 },
    { day: 'Mon', date: '19 Oct', sales: metrics.todayCashSales + metrics.todayLedgerSales || 187000, profit: 34000, isCurrent: true },
    { day: 'Tue', date: '20 Oct', sales: 0, profit: 0 }
  ];

  const maxVal = Math.max(...weekData.map(d => chartMode === 'sales' ? d.sales : d.profit), 100000);

  return (
    <div className="page-body">
      {/* 4 Main KPI Cards matching Screenshot 2 */}
      <div className="kpi-grid">
        {/* Card 1: Today's Cash Sale */}
        <div className="kpi-card">
          <div className="kpi-header">
            <span className="kpi-title">TODAY&apos;S CASH SALE</span>
            <span className="kpi-icon-pill" style={{ background: '#dcfce7', color: '#16a34a' }}>
              💵
            </span>
          </div>
          <div className="kpi-value">{formatCurrency(metrics.todayCashSales, hideAmounts)}</div>
          <div className="kpi-subtext">
            <span>&uarr;</span>
            <span>{metrics.todayCashCount} cash sale receipts</span>
          </div>
        </div>

        {/* Card 2: Today's Ledger Sale */}
        <div className="kpi-card">
          <div className="kpi-header">
            <span className="kpi-title">TODAY&apos;S LEDGER SALE</span>
            <span className="kpi-icon-pill" style={{ background: '#eff6ff', color: '#2563eb' }}>
              👥
            </span>
          </div>
          <div className="kpi-value">{formatCurrency(metrics.todayLedgerSales, hideAmounts)}</div>
          <div className="kpi-subtext">
            <span>&uarr;</span>
            <span>{metrics.todayLedgerCount} ledger invoices</span>
          </div>
        </div>

        {/* Card 3: Cash In Hand */}
        <div className="kpi-card">
          <div className="kpi-header">
            <span className="kpi-title">CASH IN HAND</span>
            <span className="kpi-icon-pill" style={{ background: '#f3e8ff', color: '#9333ea' }}>
              👛
            </span>
          </div>
          <div className="kpi-value">{formatCurrency(metrics.cashInHand, hideAmounts)}</div>
          <div className="kpi-subtext">
            <span>&uarr;</span>
            <span>{metrics.cashTransactionsToday} cash transactions today</span>
          </div>
        </div>

        {/* Card 4: Products In Stock */}
        <div className="kpi-card" onClick={() => setActiveTab('inventory')} style={{ cursor: 'pointer' }}>
          <div className="kpi-header">
            <span className="kpi-title">PRODUCTS IN STOCK</span>
            <span className="kpi-icon-pill" style={{ background: '#fef3c7', color: '#d97706' }}>
              📦
            </span>
          </div>
          <div className="kpi-value">
            {formatNumber(metrics.totalStockUnits, hideAmounts)} / {metrics.totalProducts}
          </div>
          <div className="kpi-subtext" style={{ color: metrics.lowStockCount > 0 ? '#ef4444' : undefined }}>
            <span>{metrics.lowStockCount} low/out of stock attention</span>
          </div>
        </div>
      </div>

      {/* Grid: Sales Overview Chart (Left) & Recent Sales Today Table (Right) */}
      <div className="dashboard-grid">
        {/* Sales Overview Chart Card */}
        <div className="card">
          <div className="card-header">
            <div className="card-title">
              <span dangerouslySetInnerHTML={{ __html: icons.reports }} />
              <span>Sales Overview</span>
            </div>

            <div className="card-controls">
              {/* Sales vs Profit Toggle */}
              <div className="segmented-control">
                <button
                  type="button"
                  className={`segmented-btn ${chartMode === 'sales' ? 'active' : ''}`}
                  onClick={() => setChartMode('sales')}
                >
                  Sales
                </button>
                <button
                  type="button"
                  className={`segmented-btn ${chartMode === 'profit' ? 'active' : ''}`}
                  onClick={() => setChartMode('profit')}
                >
                  Profit/Loss
                </button>
              </div>

              {/* Timeframe Toggle */}
              <div className="segmented-control">
                <button
                  type="button"
                  className={`segmented-btn ${timeframe === 'week' ? 'active' : ''}`}
                  onClick={() => setTimeframe('week')}
                >
                  Week
                </button>
                <button
                  type="button"
                  className={`segmented-btn ${timeframe === 'month' ? 'active' : ''}`}
                  onClick={() => setTimeframe('month')}
                >
                  Month
                </button>
                <button
                  type="button"
                  className={`segmented-btn ${timeframe === 'year' ? 'active' : ''}`}
                  onClick={() => setTimeframe('year')}
                >
                  Year
                </button>
              </div>
            </div>
          </div>

          {/* Interactive Chart Canvas */}
          <div style={{ padding: '16px 8px 8px 8px', height: '240px', display: 'flex', flexDirection: 'column', justifyContent: 'flex-end' }}>
            <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', height: '180px', gap: '8px', borderBottom: '1px solid var(--border-color)', paddingBottom: '8px' }}>
              {weekData.map((d, idx) => {
                const val = chartMode === 'sales' ? d.sales : d.profit;
                const heightPct = Math.max(8, Math.min(100, Math.round((val / maxVal) * 100)));
                return (
                  <div key={idx} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', height: '100%', justifyContent: 'flex-end' }}>
                    <div style={{ fontSize: '10px', color: 'var(--text-muted)', marginBottom: '4px', fontWeight: 600 }}>
                      {formatCurrency(val, hideAmounts).replace('Rs ', '')}
                    </div>
                    <div
                      style={{
                        width: '80%',
                        maxWidth: '42px',
                        height: `${heightPct}%`,
                        background: d.isCurrent ? 'var(--primary)' : 'var(--border-color)',
                        borderRadius: '4px 4px 0 0',
                        transition: 'all 0.3s ease',
                        boxShadow: d.isCurrent ? '0 4px 12px rgba(37, 99, 235, 0.3)' : 'none',
                        cursor: 'pointer'
                      }}
                      title={`${d.day} (${d.date}): ${formatCurrency(val)}`}
                    />
                    <div style={{ fontSize: '11px', marginTop: '6px', fontWeight: d.isCurrent ? 700 : 500, color: d.isCurrent ? 'var(--primary)' : 'var(--text-muted)' }}>
                      {d.day}
                    </div>
                  </div>
                );
              })}
            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: '10px', gap: '16px', fontSize: '11px', color: 'var(--text-muted)' }}>
              <span style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
                <span style={{ width: '10px', height: '10px', background: 'var(--primary)', borderRadius: '2px', display: 'inline-block' }} />
                Current Period
              </span>
              <span style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
                <span style={{ width: '10px', height: '10px', background: 'var(--border-color)', borderRadius: '2px', display: 'inline-block' }} />
                Past Days
              </span>
            </div>
          </div>
        </div>

        {/* Recent Sales Today Card */}
        <div className="card">
          <div className="card-header">
            <div>
              <div className="card-title">
                <span>🕒</span>
                <span>Recent Sales Today</span>
              </div>
              <p style={{ fontSize: '11.5px', color: 'var(--text-muted)', marginTop: '2px' }}>
                Latest transactions with time
              </p>
            </div>

            <div className="card-controls">
              {/* Date Stepper */}
              <div style={{ display: 'flex', alignItems: 'center', background: 'var(--bg-hover)', border: '1px solid var(--border-color)', borderRadius: 'var(--radius-sm)' }}>
                <button
                  type="button"
                  style={{ border: 'none', background: 'transparent', padding: '4px 8px', cursor: 'pointer' }}
                  onClick={() => stepDate(-1)}
                  title="Previous Day"
                >
                  &lsaquo;
                </button>
                <span style={{ fontSize: '12px', fontWeight: 600, padding: '0 6px' }}>
                  {formatDateShort(selectedDate)}
                </span>
                <button
                  type="button"
                  style={{ border: 'none', background: 'transparent', padding: '4px 8px', cursor: 'pointer' }}
                  onClick={() => stepDate(1)}
                  title="Next Day"
                >
                  &rsaquo;
                </button>
              </div>

              <button
                type="button"
                className="btn btn-outline"
                style={{ fontSize: '11.5px', padding: '4px 8px' }}
                onClick={() => setActiveTab('sales')}
              >
                <span>View all</span>
              </button>
            </div>
          </div>

          {/* Table */}
          <div className="table-responsive" style={{ maxHeight: '240px' }}>
            <table className="data-table">
              <thead>
                <tr>
                  <th>CUSTOMER &uarr;</th>
                  <th>TIME &uarr;</th>
                  <th>PRODUCT &uarr;</th>
                  <th>QTY &uarr;</th>
                  <th>AMOUNT &uarr;</th>
                  <th>ACTIONS</th>
                </tr>
              </thead>
              <tbody>
                {filteredSales.length === 0 ? (
                  <tr>
                    <td colSpan={6} style={{ textAlign: 'center', padding: '36px', color: 'var(--text-muted)' }}>
                      No sales recorded for selected date
                    </td>
                  </tr>
                ) : (
                  filteredSales.map((sale) => (
                    <tr key={sale.id}>
                      <td style={{ fontWeight: 600 }}>{sale.customerName}</td>
                      <td style={{ fontSize: '11.5px', color: 'var(--text-muted)' }}>
                        {new Date(sale.date).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' })}
                      </td>
                      <td>
                        <span style={{ fontSize: '12px' }}>
                          {sale.items[0]?.name || 'Agri items'}
                          {sale.items.length > 1 ? ` (+${sale.items.length - 1} more)` : ''}
                        </span>
                      </td>
                      <td>
                        <span className="badge badge-neutral">
                          {sale.items.reduce((s, i) => s + i.qty, 0)} {sale.items[0]?.unit || 'bags'}
                        </span>
                      </td>
                      <td style={{ fontWeight: 700 }}>
                        {formatCurrency(sale.grandTotal, hideAmounts)}
                      </td>
                      <td>
                        <button
                          type="button"
                          className="btn btn-outline btn-icon-only"
                          title="View & Print Invoice"
                          onClick={() => onOpenInvoiceView && onOpenInvoiceView(sale)}
                        >
                          👁️
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}
